CREATE SCHEMA IF NOT EXISTS "public";
CREATE TYPE "Handedness" AS ENUM ('RIGHT', 'LEFT');
CREATE TYPE "ExerciseType" AS ENUM ('CHROMATIC', 'SCALE', 'FINGER_DEXTERITY');
CREATE TYPE "Difficulty" AS ENUM ('BEGINNER', 'INTERMEDIATE', 'ADVANCED');
CREATE TYPE "SessionStatus" AS ENUM ('IN_PROGRESS', 'COMPLETED', 'ABANDONED');
CREATE TYPE "AnalysisStatus" AS ENUM ('QUEUED', 'PROCESSING', 'COMPLETED', 'FAILED');
CREATE TYPE "FeedbackCategory" AS ENUM ('PITCH', 'RHYTHM', 'TECHNIQUE', 'BEND', 'OTHER');
CREATE TYPE "FeedbackSeverity" AS ENUM ('INFO', 'WARNING', 'ERROR');
CREATE TABLE "User" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "displayName" TEXT, "handedness" "Handedness" NOT NULL DEFAULT 'RIGHT', "tuning" TEXT NOT NULL DEFAULT 'E2,A2,D3,G3,B3,E4', "timezone" TEXT NOT NULL DEFAULT 'UTC', "refreshTokenHash" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Exercise" ("id" TEXT NOT NULL, "slug" TEXT NOT NULL, "type" "ExerciseType" NOT NULL, "difficulty" "Difficulty" NOT NULL DEFAULT 'BEGINNER', "title" TEXT NOT NULL, "description" TEXT, "instructions" TEXT, "configuration" JSONB NOT NULL, "referenceAudioUrl" TEXT, "isPublished" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Exercise_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PracticeSession" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "exerciseId" TEXT, "pieceTitle" TEXT, "sheetMusicUrl" TEXT, "backingTrackUrl" TEXT, "status" "SessionStatus" NOT NULL DEFAULT 'IN_PROGRESS', "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PracticeSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PerformanceRecording" ("id" TEXT NOT NULL, "sessionId" TEXT NOT NULL, "storageKey" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "durationMs" INTEGER, "recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PerformanceRecording_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PerformanceAnalysis" ("id" TEXT NOT NULL, "recordingId" TEXT NOT NULL, "status" "AnalysisStatus" NOT NULL DEFAULT 'QUEUED', "modelVersion" TEXT, "overallScore" DOUBLE PRECISION, "pitchScore" DOUBLE PRECISION, "rhythmScore" DOUBLE PRECISION, "techniqueScore" DOUBLE PRECISION, "summary" TEXT, "errorMessage" TEXT, "startedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PerformanceAnalysis_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PerformanceFeedback" ("id" TEXT NOT NULL, "analysisId" TEXT NOT NULL, "category" "FeedbackCategory" NOT NULL, "severity" "FeedbackSeverity" NOT NULL, "startMs" INTEGER, "endMs" INTEGER, "message" TEXT NOT NULL, "suggestion" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PerformanceFeedback_pkey" PRIMARY KEY ("id"));
CREATE TABLE "UserProgress" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "totalSessions" INTEGER NOT NULL DEFAULT 0, "totalPracticeSeconds" INTEGER NOT NULL DEFAULT 0, "currentDayStreak" INTEGER NOT NULL DEFAULT 0, "longestDayStreak" INTEGER NOT NULL DEFAULT 0, "lastPracticedOn" TIMESTAMP(3), "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "UserProgress_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "Exercise_slug_key" ON "Exercise"("slug"); CREATE INDEX "Exercise_type_difficulty_isPublished_idx" ON "Exercise"("type", "difficulty", "isPublished"); CREATE INDEX "PracticeSession_userId_startedAt_idx" ON "PracticeSession"("userId", "startedAt"); CREATE INDEX "PracticeSession_exerciseId_idx" ON "PracticeSession"("exerciseId"); CREATE UNIQUE INDEX "PerformanceRecording_storageKey_key" ON "PerformanceRecording"("storageKey"); CREATE INDEX "PerformanceRecording_sessionId_recordedAt_idx" ON "PerformanceRecording"("sessionId", "recordedAt"); CREATE UNIQUE INDEX "PerformanceAnalysis_recordingId_key" ON "PerformanceAnalysis"("recordingId"); CREATE INDEX "PerformanceAnalysis_status_createdAt_idx" ON "PerformanceAnalysis"("status", "createdAt"); CREATE INDEX "PerformanceFeedback_analysisId_startMs_idx" ON "PerformanceFeedback"("analysisId", "startMs"); CREATE UNIQUE INDEX "UserProgress_userId_key" ON "UserProgress"("userId");
ALTER TABLE "PracticeSession" ADD CONSTRAINT "PracticeSession_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PracticeSession" ADD CONSTRAINT "PracticeSession_exerciseId_fkey" FOREIGN KEY ("exerciseId") REFERENCES "Exercise"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "PerformanceRecording" ADD CONSTRAINT "PerformanceRecording_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "PracticeSession"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PerformanceAnalysis" ADD CONSTRAINT "PerformanceAnalysis_recordingId_fkey" FOREIGN KEY ("recordingId") REFERENCES "PerformanceRecording"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PerformanceFeedback" ADD CONSTRAINT "PerformanceFeedback_analysisId_fkey" FOREIGN KEY ("analysisId") REFERENCES "PerformanceAnalysis"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "UserProgress" ADD CONSTRAINT "UserProgress_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
